  -- ── Dua Categories & Duas ────────────────────────
  insert into dua_categories (tenant_id, slug, title, subtitle, icon, display_type, sort_order)
    values (v_tenant_id, 'masnoon', 'Daily Masnoon Duas', 'Morning & Evening Supplications', 'stars', 'list_screen', 1) returning id into v_cat_id;
  insert into duas (tenant_id, category_id, title, subtitle, arabic_text, translation_en, icon, sort_order)
    values (v_tenant_id, v_cat_id, 'Dua e Subah', 'Morning Dua', 'اَللّٰهُمَّ بِكَ اَصْبَحْنَا وَبِكَ اَمْسَيْنَا وَبِكَ نَحْيَا وَبِكَ نَمُوْتُ وَاِلَيْكَ النُّشُوْرُ', '"O Allah, by You we enter the morning, by You we enter the evening, by You we live, by You we die, and to You is the resurrection."', 'wb_sunny', 1);
  insert into duas (tenant_id, category_id, title, subtitle, arabic_text, translation_en, icon, sort_order)
    values (v_tenant_id, v_cat_id, 'Dua e Shaam', 'Evening Dua', 'اَللّٰهُمَّ بِكَ اَمْسَيْنَا وَبِكَ اَصْبَحْنَا وَبِكَ نَحْيَا وَبِكَ نَمُوْتُ وَاِلَيْكَ الْمَصِيْرُ', '"O Allah, by You we enter the evening, by You we enter the morning, by You we live, by You we die, and to You is the return."', 'dark_mode', 2);
  insert into duas (tenant_id, category_id, title, subtitle, arabic_text, translation_en, icon, sort_order)
    values (v_tenant_id, v_cat_id, 'Ghar Se Nikalnay Ki Dua', 'Leaving Home', 'بِسْمِ اللهِ تَوَكَّلْتُ عَلَى اللهِ وَلَا حَوْلَ وَلَا قُوَّةَ اِلَّا بِاللهِ', '"In the name of Allah, I place my trust in Allah, and there is no power and no strength except with Allah."', 'home', 3);
  insert into duas (tenant_id, category_id, title, subtitle, arabic_text, translation_en, icon, sort_order)
    values (v_tenant_id, v_cat_id, 'Ghar Mein Daakhil Honay Ki Dua', 'Entering Home', 'اَللّٰهُمَّ اِنِّىْ اَسْئَلُكَ خَيْرَ الْمَوْلِجِ وَخَيْرَ الْمَخْرَجِ', '"O Allah, I ask You for the best entry and the best exit."', 'door_front', 4);
  insert into duas (tenant_id, category_id, title, subtitle, arabic_text, translation_en, icon, sort_order)
    values (v_tenant_id, v_cat_id, 'Khanay Se Pehle Ki Dua', 'Before Eating', 'بِسْمِ اللهِ وَعَلٰى بَرَكَةِ اللهِ', '"In the name of Allah and with the blessings of Allah."', 'restaurant', 5);
  insert into duas (tenant_id, category_id, title, subtitle, arabic_text, translation_en, icon, sort_order)
    values (v_tenant_id, v_cat_id, 'Khanay Ky Baad Ki Dua', 'After Eating', 'اَلْحَمْدُ لِلّٰهِ الَّذِيْ اَطْعَمَنَا وَسَقَانَا وَجَعَلَنَا مُسْلِمِيْنَ', '"All praise is for Allah Who fed us, gave us drink, and made us Muslims."', 'check_circle', 6);
  insert into duas (tenant_id, category_id, title, subtitle, arabic_text, translation_en, icon, sort_order)
    values (v_tenant_id, v_cat_id, 'Wudu Shuru Karnay Ki Dua', 'Starting Wudu', 'بِسْمِ اللهِ الرَّحْمٰنِ الرَّحِيْمِ', '"In the name of Allah, the Most Gracious, the Most Merciful."', 'water_drop', 7);
  insert into duas (tenant_id, category_id, title, subtitle, arabic_text, translation_en, icon, sort_order)
    values (v_tenant_id, v_cat_id, 'Wudu Ky Baad Ki Dua', 'After Wudu', 'اَشْهَدُ اَنْ لَّا اِلٰهَ اِلَّا اللهُ وَحْدَهٗ لَا شَرِيْكَ لَهٗ وَاَشْهَدُ اَنَّ مُحَمَّدًا عَبْدُهٗ وَرَسُوْلُهٗ', '"I bear witness that there is no god but Allah, alone without partner, and I bear witness that Muhammad is His servant and messenger."', 'water_drop', 8);
  insert into duas (tenant_id, category_id, title, subtitle, arabic_text, translation_en, icon, sort_order)
    values (v_tenant_id, v_cat_id, 'Sonay Ki Dua', 'Before Sleeping', 'اَللّٰهُمَّ بِاسْمِكَ اَمُوْتُ وَاَحْيَا', '"O Allah, in Your name I die and I live."', 'bed', 9);
  insert into duas (tenant_id, category_id, title, subtitle, arabic_text, translation_en, icon, sort_order)
    values (v_tenant_id, v_cat_id, 'Neend Se Uthny Ki Dua', 'Waking Up', 'اَلْحَمْدُ لِلّٰهِ الَّذِيْ اَحْيَانَا بَعْدَ مَا اَمَاتَنَا وَاِلَيْهِ النُّشُوْرُ', '"All praise is for Allah Who gave us life after death and to Him is the resurrection."', 'alarm', 10);
  insert into duas (tenant_id, category_id, title, subtitle, arabic_text, translation_en, icon, sort_order)
    values (v_tenant_id, v_cat_id, 'Toilet Jaane Ki Dua', 'Entering Toilet', 'اَللّٰهُمَّ اِنِّىْ اَعُوْذُبِكَ مِنَ الْخُبُثِ وَالْخَبَآئِثِ', '"O Allah, I seek Your protection from male and female devils."', 'wc', 11);
  insert into duas (tenant_id, category_id, title, subtitle, arabic_text, translation_en, icon, sort_order)
    values (v_tenant_id, v_cat_id, 'Toilet Se Nikalnay Ki Dua', 'Leaving Toilet', 'غُفْرَانَكَ', '"I seek Your forgiveness."', 'exit_to_app', 12);
  insert into duas (tenant_id, category_id, title, subtitle, arabic_text, translation_en, icon, sort_order)
    values (v_tenant_id, v_cat_id, 'Masjid Mein Daakhil Honay Ki Dua', 'Entering Mosque', 'اَللّٰهُمَّ افْتَحْ لِيْ اَبْوَابَ رَحْمَتِكَ', '"O Allah, open for me the doors of Your mercy."', 'mosque', 13);
  insert into duas (tenant_id, category_id, title, subtitle, arabic_text, translation_en, icon, sort_order)
    values (v_tenant_id, v_cat_id, 'Masjid Se Nikalnay Ki Dua', 'Leaving Mosque', 'اَللّٰهُمَّ اِنِّىْ اَسْئَلُكَ مِنْ فَضْلِكَ', '"O Allah, I ask You from Your bounty."', 'logout', 14);
  insert into duas (tenant_id, category_id, title, subtitle, arabic_text, translation_en, icon, sort_order)
    values (v_tenant_id, v_cat_id, 'Safar Ki Dua', 'Travelling', 'سُبْحَانَ الَّذِيْ سَخَّرَلَنَا هٰذَا وَمَا كُنَّا لَهٗ مُقْرِنِيْنَ وَاِنَّآ اِلٰى رَبِّنَا لَمُنْقَلِبُوْنَ', '"Glory be to Him Who has subjected this to us, and we were not able to do it, and surely to our Lord we must return."', 'directions_car', 15);
  insert into duas (tenant_id, category_id, title, subtitle, arabic_text, translation_en, icon, sort_order)
    values (v_tenant_id, v_cat_id, 'Beemar Ki Iyaadat Ki Dua', 'Visiting the Sick', 'لَا بَاْسَ طَهُوْرٌ اِنْ شَآءَ اللهُ', '"Do not worry, it is a purification, if Allah wills."', 'local_hospital', 16);
  insert into duas (tenant_id, category_id, title, subtitle, arabic_text, translation_en, icon, sort_order)
    values (v_tenant_id, v_cat_id, 'Dua e Qunoot', 'Witr Prayer', 'اَللّٰهُمَّ اِنَّا نَسْتَعِيْنُكَ وَنَسْتَغْفِرُكَ وَنُؤْمِنُ بِكَ وَنَتَوَكَّلُ عَلَيْكَ وَنُثْنِيْ عَلَيْكَ الْخَيْرَ', '"O Allah, we seek Your help and ask Your forgiveness and believe in You and trust in You and praise You in the best way."', 'favorite', 17);
  insert into duas (tenant_id, category_id, title, subtitle, arabic_text, translation_en, icon, sort_order)
    values (v_tenant_id, v_cat_id, 'Baarish Ki Dua', 'During Rain', 'اَللّٰهُمَّ صَيِّبًا نَافِعًا', '"O Allah, make it a beneficial rain."', 'cloud', 18);
  insert into duas (tenant_id, category_id, title, subtitle, arabic_text, translation_en, icon, sort_order)
    values (v_tenant_id, v_cat_id, 'Aandhi Ki Dua', 'During Storm', 'اَللّٰهُمَّ اِنِّىْ اَسْئَلُكَ خَيْرَهَا وَخَيْرَ مَا فِيْهَا وَاَعُوْذُبِكَ مِنْ شَرِّهَا وَشَرِّ مَا فِيْهَا', '"O Allah, I ask You for its good and the good within it, and I seek refuge in You from its evil and the evil within it."', 'thunderstorm', 19);
  insert into duas (tenant_id, category_id, title, subtitle, arabic_text, translation_en, icon, sort_order)
    values (v_tenant_id, v_cat_id, 'Naya Chand Dekhne Ki Dua', 'Seeing New Moon', 'اَللّٰهُ اَكْبَرُ اَللّٰهُمَّ اَهِلَّهٗ عَلَيْنَا بِالْيُمْنِ وَالْاِيْمَانِ', '"Allah is the Greatest. O Allah, let this moon appear over us with blessings and faith."', 'search', 20);
  insert into duas (tenant_id, category_id, title, subtitle, arabic_text, translation_en, icon, sort_order)
    values (v_tenant_id, v_cat_id, 'Qarz Ada Honay Ki Dua', 'Paying Off Debt', 'اَللّٰهُمَّ اكْفِنِيْ بِحَلَالِكَ عَنْ حَرَامِكَ وَاَغْنِنِيْ بِفَضْلِكَ عَمَّنْ سِوَاكَ', '"O Allah, suffice me with what You have made lawful against what You have forbidden, and make me independent with Your bounty."', 'credit_card', 21);
  insert into duas (tenant_id, category_id, title, subtitle, arabic_text, translation_en, icon, sort_order)
    values (v_tenant_id, v_cat_id, 'Naye Bachay Ki Dua', 'Newborn Baby', 'بَارَكَ اللهُ لَكَ فِي الْمَوْهُوْبِ لَكَ وَشَكَرْتَ الْوَاهِبَ وَبَلَغَ اَشُدَّهٗ وَرُزِقْتَ بِرَّهٗ', '"May Allah bless you in what was given to you, may you be grateful to the Giver, and may he reach maturity and may you be granted his righteousness."', 'child_care', 22);
  insert into duas (tenant_id, category_id, title, subtitle, arabic_text, translation_en, icon, sort_order)
    values (v_tenant_id, v_cat_id, 'Ilm Mein Izafa Ki Dua', 'Seeking Knowledge', 'رَبِّ زِدْنِيْ عِلْمًا', '"O my Lord, increase me in knowledge."', 'school', 23);
  insert into duas (tenant_id, category_id, title, subtitle, arabic_text, translation_en, icon, sort_order)
    values (v_tenant_id, v_cat_id, 'Gham Aur Pareshani Ki Dua', 'Grief & Worry', 'اَللّٰهُمَّ اِنِّىْ عَبْدُكَ وَابْنُ عَبْدِكَ وَابْنُ اَمَتِكَ نَاصِيَتِيْ بِيَدِكَ', '"O Allah, I am Your servant, son of Your servant, son of Your maidservant. My forelock is in Your hand."', 'psychology', 24);
  insert into duas (tenant_id, category_id, title, subtitle, arabic_text, translation_en, icon, sort_order)
    values (v_tenant_id, v_cat_id, 'Beemar Hone Ki Dua', 'When Sick', 'اَللّٰهُمَّ اَذْهِبِ الْبَاْسَ رَبَّ النَّاسِ اشْفِ وَاَنْتَ الشَّافِيْ', '"O Allah, remove the hardship, O Lord of mankind, grant cure, for You are the Healer."', 'healing', 25);
  insert into duas (tenant_id, category_id, title, subtitle, arabic_text, translation_en, icon, sort_order)
    values (v_tenant_id, v_cat_id, 'Shaitaan Se Bachne Ki Dua', 'Protection from Shaitan', 'اَعُوْذُ بِاللهِ مِنَ الشَّيْطَانِ الرَّجِيْمِ', '"I seek refuge in Allah from the accursed devil."', 'shield', 26);
  insert into duas (tenant_id, category_id, title, subtitle, arabic_text, translation_en, icon, sort_order)
    values (v_tenant_id, v_cat_id, 'Aainay Mein Dekhne Ki Dua', 'Looking in Mirror', 'اَللّٰهُمَّ اَنْتَ حَسَّنْتَ خَلْقِيْ فَحَسِّنْ خُلُقِيْ', '"O Allah, just as You have made my appearance beautiful, make my character beautiful too."', 'looks', 27);
  insert into duas (tenant_id, category_id, title, subtitle, arabic_text, translation_en, icon, sort_order)
    values (v_tenant_id, v_cat_id, 'Bazaar Mein Daakhil Honay Ki Dua', 'Entering Market', 'لَا اِلٰهَ اِلَّا اللهُ وَحْدَهٗ لَا شَرِيْكَ لَهٗ لَهُ الْمُلْكُ وَلَهُ الْحَمْدُ يُحْيِيْ وَيُمِيْتُ وَهُوَ حَيٌّ لَّا يَمُوْتُ', '"There is no god but Allah, alone without partner. His is the dominion and His is the praise. He gives life and causes death and He is living and never dies."', 'store', 28);
  insert into duas (tenant_id, category_id, title, subtitle, arabic_text, translation_en, icon, sort_order)
    values (v_tenant_id, v_cat_id, 'Nikah Ki Dua', 'At Marriage', 'بَارَكَ اللهُ لَكَ وَبَارَكَ عَلَيْكَ وَجَمَعَ بَيْنَكُمَا فِيْ خَيْرٍ', '"May Allah bless you and shower blessings upon you and join you together in goodness."', 'handshake', 29);
  insert into duas (tenant_id, category_id, title, subtitle, arabic_text, translation_en, icon, sort_order)
    values (v_tenant_id, v_cat_id, 'Istighfar', 'Seeking Forgiveness', 'اَسْتَغْفِرُ اللهَ الَّذِيْ لَا اِلٰهَ اِلَّا هُوَ الْحَيُّ الْقَيُّوْمُ وَاَتُوْبُ اِلَيْهِ', '"I seek forgiveness from Allah, besides Whom there is no god, the Ever-Living, the Self-Sustaining, and I turn to Him in repentance."', 'circle', 30);
  insert into duas (tenant_id, category_id, title, subtitle, arabic_text, translation_en, icon, sort_order)
    values (v_tenant_id, v_cat_id, 'Achha Kaam Khatam Honay Ki Dua', 'Completing Good Work', 'اَلْحَمْدُ لِلّٰهِ الَّذِيْ بِنِعْمَتِهٖ تَتِمُّ الصَّالِحَاتُ', '"All praise is for Allah by Whose blessing all good deeds are completed."', 'sports_soccer', 31);
  insert into duas (tenant_id, category_id, title, subtitle, arabic_text, translation_en, icon, sort_order)
    values (v_tenant_id, v_cat_id, 'Sadqa Dene Ki Dua', 'Giving Charity', 'رَبَّنَا تَقَبَّلْ مِنَّا اِنَّكَ اَنْتَ السَّمِيْعُ الْعَلِيْمُ', '"Our Lord, accept from us. Indeed You are the All-Hearing, the All-Knowing."', 'volunteer_activism', 32);
  insert into duas (tenant_id, category_id, title, subtitle, arabic_text, translation_en, icon, sort_order)
    values (v_tenant_id, v_cat_id, 'Mushkil Waqt Ki Dua', 'Times of Difficulty', 'اِنَّا لِلّٰهِ وَاِنَّآ اِلَيْهِ رٰجِعُوْنَ', '"Indeed we belong to Allah and indeed to Him we shall return."', 'airline_seat_flat', 33);
  insert into duas (tenant_id, category_id, title, subtitle, arabic_text, translation_en, icon, sort_order)
    values (v_tenant_id, v_cat_id, 'Darood Ibrahim', 'Sending Blessings', 'اَللّٰهُمَّ صَلِّ عَلٰى مُحَمَّدٍ وَّعَلٰى اٰلِ مُحَمَّدٍ كَمَا صَلَّيْتَ عَلٰى اِبْرَاهِيْمَ وَعَلٰى اٰلِ اِبْرَاهِيْمَ', '"O Allah, send blessings upon Muhammad and the family of Muhammad, as You sent blessings upon Ibrahim and the family of Ibrahim."', 'star', 34);
  insert into duas (tenant_id, category_id, title, subtitle, arabic_text, translation_en, icon, sort_order)
    values (v_tenant_id, v_cat_id, 'Sayyidul Istighfar', 'Master of Forgiveness', 'اَللّٰهُمَّ اَنْتَ رَبِّيْ لَا اِلٰهَ اِلَّا اَنْتَ خَلَقْتَنِيْ وَاَنَا عَبْدُكَ وَاَنَا عَلٰى عَهْدِكَ وَوَعْدِكَ مَا اسْتَطَعْتُ', '"O Allah, You are my Lord, there is no god but You. You created me and I am Your servant, and I abide by Your covenant and promise as best I can."', 'auto_awesome', 35);

  insert into dua_categories (tenant_id, slug, title, subtitle, icon, display_type, sort_order)
    values (v_tenant_id, 'kalimas', '6 Kalimas', 'Foundations of Faith', 'format_list_numbered', 'modal', 2) returning id into v_cat_id;
  insert into duas (tenant_id, category_id, title, arabic_text, translation_en, numbered_position, sort_order)
    values (v_tenant_id, v_cat_id, 'Kalima Tayyiba', 'لَآ اِلٰهَ اِلَّا اللهُ مُحَمَّدٌ رَّسُوْلُ اللهِ', '"There is no god but Allah, Muhammad is the Messenger of Allah."', 1, 1);
  insert into duas (tenant_id, category_id, title, arabic_text, translation_en, numbered_position, sort_order)
    values (v_tenant_id, v_cat_id, 'Kalima Shahadat', 'اَشْهَدُ اَنْ لَّآ اِلٰهَ اِلَّا اللهُ وَحْدَهٗ لَا شَرِيْكَ لَهٗ وَاَشْهَدُ اَنَّ مُحَمَّدًا عَبْدُهٗ وَرَسُوْلُهٗ', '"I bear witness that there is no god but Allah, alone without any partner, and I bear witness that Muhammad is His servant and messenger."', 2, 2);
  insert into duas (tenant_id, category_id, title, arabic_text, translation_en, numbered_position, sort_order)
    values (v_tenant_id, v_cat_id, 'Kalima Tamjeed', 'سُبْحَانَ اللهِ وَالْحَمْدُ لِلّٰهِ وَلَآ اِلٰهَ اِلَّا اللهُ وَاللهُ اَكْبَرُ وَلَا حَوْلَ وَلَا قُوَّةَ اِلَّا بِاللهِ الْعَلِيِّ الْعَظِيْمِ', '"Glory be to Allah, and praise be to Allah, and there is no god but Allah, and Allah is the Greatest, and there is no power and no strength except with Allah, the Most High, the Most Great."', 3, 3);
  insert into duas (tenant_id, category_id, title, arabic_text, translation_en, numbered_position, sort_order)
    values (v_tenant_id, v_cat_id, 'Kalima Tauheed', 'لَآ اِلٰهَ اِلَّا اللهُ وَحْدَهٗ لَا شَرِيْكَ لَهٗ لَهُ الْمُلْكُ وَلَهُ الْحَمْدُ يُحْيٖ وَيُمِيْتُ وَهُوَ حَيٌّ لَّا يَمُوْتُ اَبَدًا اَبَدًا ذُو الْجَلَالِ وَالْاِكْرَامِ بِيَدِهِ الْخَيْرُ وَهُوَ عَلٰى كُلِّ شَيْءٍ قَدِيْرٌ', '"There is no god but Allah, alone without any partner. To Him belongs the kingdom and to Him belongs all praise. He gives life and causes death, and He is Ever-Living and will never die. Ever. He is the Lord of Majesty and Honor. In His hand is all goodness, and He has power over all things."', 4, 4);
  insert into duas (tenant_id, category_id, title, arabic_text, translation_en, numbered_position, sort_order)
    values (v_tenant_id, v_cat_id, 'Kalima Astaghfar', 'اَسْتَغْفِرُ اللهَ رَبِّيْ مِنْ كُلِّ ذَنْبٍ اَذْنَبْتُهٗ عَمَدًا اَوْ خَطَاً سِرًّا اَوْ عَلَانِيَةً وَّاَتُوْبُ اِلَيْهِ مِنَ الذَّنْبِ الَّذِيْ اَعْلَمُ وَمِنَ الذَّنْبِ الَّذِيْ لَآ اَعْلَمُ اِنَّكَ اَنْتَ عَلَّامُ الْغُيُوْبِ وَسَتَّارُ الْعُيُوْبِ وَغَفَّارُ الذُّنُوْبِ وَلَا حَوْلَ وَلَا قُوَّةَ اِلَّا بِاللهِ الْعَلِيِّ الْعَظِيْمِ', '"I seek forgiveness from Allah, my Lord, for every sin I have committed intentionally or by mistake, secretly or openly. I repent to Him for sins I know and those I do not know. Surely You are the Knower of the unseen, the Concealer of faults, and the Forgiver of sins."', 5, 5);
  insert into duas (tenant_id, category_id, title, arabic_text, translation_en, numbered_position, sort_order)
    values (v_tenant_id, v_cat_id, 'Kalima Radde Kufr', 'اَللّٰهُمَّ اِنِّيْ اَعُوْذُبِكَ مِنْ اَنْ اُشْرِكَ بِكَ شَيْئًا وَّاَنَا اَعْلَمُ بِهٖ وَاَسْتَغْفِرُكَ لِمَا لَآ اَعْلَمُ بِهٖ تُبْتُ عَنْهُ وَتَبَرَّاْتُ مِنَ الْكُفْرِ وَالشِّرْكِ وَالْكِذْبِ وَالْغِيْبَةِ وَالْبِدْعَةِ وَالنَّمِيْمَةِ وَالْفَوَاحِشِ وَالْبُهْتَانِ وَالْمَعَاصِيْ كُلِّهَا وَاَسْلَمْتُ وَاَقُوْلُ لَآ اِلٰهَ اِلَّا اللهُ مُحَمَّدٌ رَّسُوْلُ اللهِ', '"O Allah! I seek refuge in You from knowingly associating any partner with You, and I seek Your forgiveness for those sins I am unaware of. I repent from disbelief, polytheism, lies, backbiting, innovation, slander, shameful acts, false accusations, and all sins. I submit to You and declare: There is no god but Allah, Muhammad is the Messenger of Allah."', 6, 6);

  insert into dua_categories (tenant_id, slug, title, subtitle, icon, display_type, sort_order)
    values (v_tenant_id, 'ayat_kursi', 'Ayat-ul-Kursi', 'The Throne Verse', 'star_outline', 'modal', 3) returning id into v_cat_id;
  insert into duas (tenant_id, category_id, title, arabic_text, translation_en, sort_order)
    values (v_tenant_id, v_cat_id, 'Ayat-ul-Kursi', 'اللّٰهُ لَآ اِلٰهَ اِلَّا هُوَ الْحَيُّ الْقَيُّوْمُ ۚ لَا تَاْخُذُهٗ سِنَةٌ وَّلَا نَوْمٌ ۚ لَهٗ مَا فِي السَّمٰوٰتِ وَمَا فِي الْاَرْضِ ۗ مَنْ ذَا الَّذِيْ يَشْفَعُ عِنْدَهٗٓ اِلَّا بِاِذْنِهٖ ۚ يَعْلَمُ مَا بَيْنَ اَيْدِيْهِمْ وَمَا خَلْفَهُمْ ۚ وَلَا يُحِيْطُوْنَ بِشَيْءٍ مِّنْ عِلْمِهٖٓ اِلَّا بِمَا شَآءَ ۚ وَسِعَ كُرْسِيُّهُ السَّمٰوٰتِ وَالْاَرْضَ ۚ وَلَا يَـُٔوْدُهٗ حِفْظُهُمَا ۚ وَهُوَ الْعَلِيُّ الْعَظِيْمُ', '"Allah — there is no deity except Him, the Ever-Living, the Sustainer. Neither drowsiness nor sleep overtakes Him. To Him belongs all in the heavens and earth. None can intercede except by His permission. He knows what is before and after them. His Kursi extends over the heavens and earth, and their preservation tires Him not. He is the Most High, the Most Great."', 1);

  insert into dua_categories (tenant_id, slug, title, subtitle, icon, display_type, sort_order)
    values (v_tenant_id, 'dua_qunoot', 'Dua-e-Qunoot', 'Recited in Witr prayers', 'volunteer_activism', 'modal', 4) returning id into v_cat_id;
  insert into duas (tenant_id, category_id, title, arabic_text, translation_en, sort_order)
    values (v_tenant_id, v_cat_id, 'Dua-e-Qunoot', 'اَللّٰهُمَّ اِنَّا نَسْتَعِيْنُكَ وَنَسْتَغْفِرُكَ وَنُؤْمِنُ بِكَ وَنَتَوَكَّلُ عَلَيْكَ وَنُثْنِيْ عَلَيْكَ الْخَيْرَ وَنَشْكُرُكَ وَلَا نَكْفُرُكَ وَنَخْلَعُ وَنَتْرُكُ مَنْ يَّفْجُرُكَ ۔ اَللّٰهُمَّ اِيَّاكَ نَعْبُدُ وَلَكَ نُصَلِّيْ وَنَسْجُدُ وَاِلَيْكَ نَسْعٰى وَنَحْفِدُ وَنَرْجُوْ رَحْمَتَكَ وَنَخْشٰى عَذَابَكَ اِنَّ عَذَابَكَ بِالْكُفَّارِ مُلْحِقٌ', '"O Allah! We seek Your help, ask Your forgiveness, believe in You, and trust You. We praise You, thank You, and are not ungrateful. We forsake those who disobey You. O Allah! We worship only You, pray and prostrate to You, hasten toward You, and hope for Your mercy while fearing Your punishment. Surely Your punishment overtakes the disbelievers."', 1);

  insert into dua_categories (tenant_id, slug, title, subtitle, icon, display_type, sort_order)
    values (v_tenant_id, 'iman_mujmal', 'Iman-e-Mujmal', 'Core belief statement', 'radio_button_checked', 'modal', 5) returning id into v_cat_id;
  insert into duas (tenant_id, category_id, title, arabic_text, translation_en, sort_order)
    values (v_tenant_id, v_cat_id, 'Iman-e-Mujmal', 'آمَنْتُ بِاللّٰهِ كَمَا هُوَ بِأَسْمَائِهِ وَصِفَاتِهِ وَقَبِلْتُ جَمِيعَ أَحْكَامِهِ إِقْرَارًا بِاللِّسَانِ وَتَصْدِيقًا بِالْقَلْبِ', '"I believe in Allah as He is, with all His names and attributes, and I accept all His commands by tongue and confirm by heart."', 1);

  insert into dua_categories (tenant_id, slug, title, subtitle, icon, display_type, sort_order)
    values (v_tenant_id, 'iman_mufassal', 'Iman-e-Mufassal', 'Core belief statement', 'radio_button_checked', 'modal', 6) returning id into v_cat_id;
  insert into duas (tenant_id, category_id, title, arabic_text, translation_en, sort_order)
    values (v_tenant_id, v_cat_id, 'Iman-e-Mufassal', 'آمَنْتُ بِاللّٰهِ وَمَلَائِكَتِهِ وَكُتُبِهِ وَرُسُلِهِ وَالْيَوْمِ الْآخِرِ وَالْقَدَرِ خَيْرِهِ وَشَرِّهِ مِنَ اللّٰهِ تَعَالَى وَالْبَعْثِ بَعْدَ الْمَوْتِ', '"I believe in Allah, His angels, His books, His messengers, the Last Day, and in destiny — its good and evil from Allah, and in resurrection after death."', 1);

  -- ── 40 Hadiths ───────────────────────────────────
  insert into hadith_collections (tenant_id, name, sort_order)
    values (v_tenant_id, '40 Hadiths', 1) returning id into v_collection_id;
  insert into hadiths (tenant_id, collection_id, hadith_number, text_en, sort_order)
    values (v_tenant_id, v_collection_id, 1, 'Actions are but by intentions and every man shall have only that which he intended.', 1);
  insert into hadiths (tenant_id, collection_id, hadith_number, text_en, sort_order)
    values (v_tenant_id, v_collection_id, 2, 'Islam has been built on five pillars: testifying that there is no deity worthy of worship except Allah and that Muhammad is the Messenger of Allah, establishing the prayer, paying the Zakat, making the pilgrimage to the House, and fasting in Ramadan.', 2);
  insert into hadiths (tenant_id, collection_id, hadith_number, text_en, sort_order)
    values (v_tenant_id, v_collection_id, 3, 'Part of the perfection of one''s Islam is his leaving that which does not concern him.', 3);
  insert into hadiths (tenant_id, collection_id, hadith_number, text_en, sort_order)
    values (v_tenant_id, v_collection_id, 4, 'None of you truly believes until he loves for his brother that which he loves for himself.', 4);
  insert into hadiths (tenant_id, collection_id, hadith_number, text_en, sort_order)
    values (v_tenant_id, v_collection_id, 5, 'A person who calls others to right guidance will have a reward as that of those who follow him.', 5);
  insert into hadiths (tenant_id, collection_id, hadith_number, text_en, sort_order)
    values (v_tenant_id, v_collection_id, 6, 'Be in this world as though you were a stranger or a traveler.', 6);
  insert into hadiths (tenant_id, collection_id, hadith_number, text_en, sort_order)
    values (v_tenant_id, v_collection_id, 7, 'Do not become angry.', 7);
  insert into hadiths (tenant_id, collection_id, hadith_number, text_en, sort_order)
    values (v_tenant_id, v_collection_id, 8, 'Allah has prescribed proficiency in all things. So if you kill, kill well; and if you slaughter, slaughter well.', 8);
  insert into hadiths (tenant_id, collection_id, hadith_number, text_en, sort_order)
    values (v_tenant_id, v_collection_id, 9, 'Fear Allah wherever you are, and follow up a bad deed with a good deed and it will wipe it out, and behave well towards people.', 9);
  insert into hadiths (tenant_id, collection_id, hadith_number, text_en, sort_order)
    values (v_tenant_id, v_collection_id, 10, 'Know that if the nation were to gather together to benefit you with anything, they would not benefit you except with something that Allah had already prescribed for you.', 10);
  insert into hadiths (tenant_id, collection_id, hadith_number, text_en, sort_order)
    values (v_tenant_id, v_collection_id, 11, 'If you feel no shame, then do as you wish.', 11);
  insert into hadiths (tenant_id, collection_id, hadith_number, text_en, sort_order)
    values (v_tenant_id, v_collection_id, 12, 'Say: I believe in Allah, and then stand firm.', 12);
  insert into hadiths (tenant_id, collection_id, hadith_number, text_en, sort_order)
    values (v_tenant_id, v_collection_id, 13, 'The doors of goodness are many: glorifying Allah, praising Allah, fasting, giving charity, enjoining what is good and forbidding what is evil.', 13);
  insert into hadiths (tenant_id, collection_id, hadith_number, text_en, sort_order)
    values (v_tenant_id, v_collection_id, 14, 'Righteousness is good character, and sin is that which wavers in your heart and which you do not want people to know about.', 14);
  insert into hadiths (tenant_id, collection_id, hadith_number, text_en, sort_order)
    values (v_tenant_id, v_collection_id, 15, 'Allah the Almighty is Good and accepts only that which is good.', 15);
  insert into hadiths (tenant_id, collection_id, hadith_number, text_en, sort_order)
    values (v_tenant_id, v_collection_id, 16, 'Let him who believes in Allah and the Last Day either speak good or keep silent; and let him who believes in Allah and the Last Day be generous to his neighbour.', 16);
  insert into hadiths (tenant_id, collection_id, hadith_number, text_en, sort_order)
    values (v_tenant_id, v_collection_id, 17, 'Do not envy one another, and do not inflate prices for one another, and do not hate one another, and do not turn away from one another.', 17);
  insert into hadiths (tenant_id, collection_id, hadith_number, text_en, sort_order)
    values (v_tenant_id, v_collection_id, 18, 'Whoever relieves a believer''s distress of the distressful aspects of this world, Allah will rescue him from a difficulty of the difficulties of the Hereafter.', 18);
  insert into hadiths (tenant_id, collection_id, hadith_number, text_en, sort_order)
    values (v_tenant_id, v_collection_id, 19, 'Whoever shows the way to something good shall have a reward similar to that of its doer.', 19);
  insert into hadiths (tenant_id, collection_id, hadith_number, text_en, sort_order)
    values (v_tenant_id, v_collection_id, 20, 'Allah is helpful to a servant as long as the servant is helpful to his brother.', 20);
  insert into hadiths (tenant_id, collection_id, hadith_number, text_en, sort_order)
    values (v_tenant_id, v_collection_id, 21, 'If you guarantee me six things on your part I shall guarantee you Paradise: speak the truth when you talk, keep a promise when you make it, when you are trusted with something fulfil your trust, avoid sexual immorality, lower your gaze, and restrain your hands from injustice.', 21);
  insert into hadiths (tenant_id, collection_id, hadith_number, text_en, sort_order)
    values (v_tenant_id, v_collection_id, 22, 'Allah has prescribed proficiency in all things. Verily Allah has prescribed proficiency in killing. If you kill then do it well.', 22);
  insert into hadiths (tenant_id, collection_id, hadith_number, text_en, sort_order)
    values (v_tenant_id, v_collection_id, 23, 'Purity is half of faith. Al-Hamdu Lillah fills the scale. SubhanAllah and Al-Hamdu Lillah fill what is between heaven and earth.', 23);
  insert into hadiths (tenant_id, collection_id, hadith_number, text_en, sort_order)
    values (v_tenant_id, v_collection_id, 24, 'On the authority of Abu Hurayrah: The Messenger of Allah said, Allah said: I am as My servant thinks I am.', 24);
  insert into hadiths (tenant_id, collection_id, hadith_number, text_en, sort_order)
    values (v_tenant_id, v_collection_id, 25, 'Whoever believes in Allah and the Last Day should speak a good word or remain silent.', 25);
  insert into hadiths (tenant_id, collection_id, hadith_number, text_en, sort_order)
    values (v_tenant_id, v_collection_id, 26, 'Make things easy and do not make them difficult, cheer the people up by conveying glad tidings to them and do not repulse them.', 26);
  insert into hadiths (tenant_id, collection_id, hadith_number, text_en, sort_order)
    values (v_tenant_id, v_collection_id, 27, 'The best of you are those who learn the Quran and teach it.', 27);
  insert into hadiths (tenant_id, collection_id, hadith_number, text_en, sort_order)
    values (v_tenant_id, v_collection_id, 28, 'Seeking knowledge is an obligation upon every Muslim.', 28);
  insert into hadiths (tenant_id, collection_id, hadith_number, text_en, sort_order)
    values (v_tenant_id, v_collection_id, 29, 'The strong man is not the one who can overpower others, but the strong man is the one who controls himself while in anger.', 29);
  insert into hadiths (tenant_id, collection_id, hadith_number, text_en, sort_order)
    values (v_tenant_id, v_collection_id, 30, 'No one of you truly believes until he desires for his brother that which he desires for himself.', 30);
  insert into hadiths (tenant_id, collection_id, hadith_number, text_en, sort_order)
    values (v_tenant_id, v_collection_id, 31, 'Whoever of you sees an evil, let him change it with his hand; and if he is not able to do so, then with his tongue; and if he is not able to do so, then with his heart.', 31);
  insert into hadiths (tenant_id, collection_id, hadith_number, text_en, sort_order)
    values (v_tenant_id, v_collection_id, 32, 'The world is a prison for the believer and a paradise for the disbeliever.', 32);
  insert into hadiths (tenant_id, collection_id, hadith_number, text_en, sort_order)
    values (v_tenant_id, v_collection_id, 33, 'Speak the truth even if it is bitter.', 33);
  insert into hadiths (tenant_id, collection_id, hadith_number, text_en, sort_order)
    values (v_tenant_id, v_collection_id, 34, 'The best of deeds is the prayer performed on time, then kindness to parents, then Jihad in the way of Allah.', 34);
  insert into hadiths (tenant_id, collection_id, hadith_number, text_en, sort_order)
    values (v_tenant_id, v_collection_id, 35, 'Take advantage of five before five: your youth before your old age, your health before your illness, your wealth before your poverty, your free time before your preoccupation, and your life before your death.', 35);
  insert into hadiths (tenant_id, collection_id, hadith_number, text_en, sort_order)
    values (v_tenant_id, v_collection_id, 36, 'Smiling at your brother is an act of charity.', 36);
  insert into hadiths (tenant_id, collection_id, hadith_number, text_en, sort_order)
    values (v_tenant_id, v_collection_id, 37, 'A good word is a charity.', 37);
  insert into hadiths (tenant_id, collection_id, hadith_number, text_en, sort_order)
    values (v_tenant_id, v_collection_id, 38, 'Whoever removes a worldly grief from a believer, Allah will remove from him one of the griefs of the Day of Resurrection.', 38);
  insert into hadiths (tenant_id, collection_id, hadith_number, text_en, sort_order)
    values (v_tenant_id, v_collection_id, 39, 'The merciful will be shown mercy by the Most Merciful. Be merciful to those on the earth and the One in the heavens will have mercy upon you.', 39);
  insert into hadiths (tenant_id, collection_id, hadith_number, text_en, sort_order)
    values (v_tenant_id, v_collection_id, 40, 'Feed the hungry, visit the sick, and free the captives.', 40);

