  -- ── 5 Pillars of Islam ───────────────────────────
  insert into pillars (tenant_id, slug, title, arabic_text, description, importance, sort_order)
    values (v_tenant_id, 'shahada', 'Shahada (Faith)', 'لَا إِلٰهَ إِلَّا الله مُحَمَّدٌ رَسُولُ الله', 'The declaration of faith is the foundational pillar of Islam. It is the sincere recitation of the statement that there is no god but Allah and Muhammad is His messenger.', 'The declaration of Shahada provides a profound sense of purpose and identity, grounding the believer''s life in the worship of the Creator.', 1) returning id into v_pillar_id;
  insert into pillar_details (tenant_id, pillar_id, detail_text, sort_order)
    values (v_tenant_id, v_pillar_id, 'The core entry point into the Muslim community.', 1);
  insert into pillar_details (tenant_id, pillar_id, detail_text, sort_order)
    values (v_tenant_id, v_pillar_id, 'Requires both verbal testimony and internal belief.', 2);
  insert into pillar_details (tenant_id, pillar_id, detail_text, sort_order)
    values (v_tenant_id, v_pillar_id, 'Unifies the concepts of Tawhid (Oneness) and Risalah (Prophethood).', 3);
  insert into pillar_guide_steps (tenant_id, pillar_id, title, description, sort_order)
    values (v_tenant_id, v_pillar_id, 'Understand the Meaning', 'Internalize the profound depth of declaring Allah as the only deity.', 1);
  insert into pillar_guide_steps (tenant_id, pillar_id, title, description, sort_order)
    values (v_tenant_id, v_pillar_id, 'Recite with Sincerity', 'The testimony should be spoken clearly with full heart and soul.', 2);
  insert into pillar_guide_steps (tenant_id, pillar_id, title, description, sort_order)
    values (v_tenant_id, v_pillar_id, 'Live the Testimony', 'Ensure daily actions align with the submission expressed in the declaration.', 3);

  insert into pillars (tenant_id, slug, title, arabic_text, description, importance, sort_order)
    values (v_tenant_id, 'salah', 'Salah (Prayer)', 'الصَّلَاة', 'The five daily prayers are the spiritual backbone of a Muslim''s life, performed at specific times from dawn until night.', 'Salah serves as a constant reminder of our connection to the Divine, purifying the heart and soul through regular devotion.', 2) returning id into v_pillar_id;
  insert into pillar_details (tenant_id, pillar_id, detail_text, sort_order)
    values (v_tenant_id, v_pillar_id, 'Performed five times daily: Fajr, Dhuhr, Asr, Maghrib, and Isha.', 1);
  insert into pillar_details (tenant_id, pillar_id, detail_text, sort_order)
    values (v_tenant_id, v_pillar_id, 'Requires ritual purity (Wudu) before starting.', 2);
  insert into pillar_details (tenant_id, pillar_id, detail_text, sort_order)
    values (v_tenant_id, v_pillar_id, 'Direct communication between the worshipper and Allah.', 3);
  insert into pillar_guide_steps (tenant_id, pillar_id, title, description, sort_order)
    values (v_tenant_id, v_pillar_id, 'Perform Wudu', 'Cleanse yourself physically and spiritually before approaching prayer.', 1);
  insert into pillar_guide_steps (tenant_id, pillar_id, title, description, sort_order)
    values (v_tenant_id, v_pillar_id, 'Face the Qibla', 'Align your direction towards the Kaaba in Makkah.', 2);
  insert into pillar_guide_steps (tenant_id, pillar_id, title, description, sort_order)
    values (v_tenant_id, v_pillar_id, 'Focus and Humility', 'Enter prayer with a present heart and complete devotion (Khushu).', 3);

  insert into pillars (tenant_id, slug, title, arabic_text, description, importance, sort_order)
    values (v_tenant_id, 'zakat', 'Zakat (Charity)', 'الزَّكَاة', 'Zakat is the obligatory giving of a portion of one''s wealth to those in need, serving as a form of social purification.', 'Zakat bridges the gap between the rich and the poor, ensuring that the wealth of the community circulates fairly.', 3) returning id into v_pillar_id;
  insert into pillar_details (tenant_id, pillar_id, detail_text, sort_order)
    values (v_tenant_id, v_pillar_id, 'Typically 2.5% of surplus wealth held for a year.', 1);
  insert into pillar_details (tenant_id, pillar_id, detail_text, sort_order)
    values (v_tenant_id, v_pillar_id, 'Purifies wealth and heart from greed and selfishness.', 2);
  insert into pillar_details (tenant_id, pillar_id, detail_text, sort_order)
    values (v_tenant_id, v_pillar_id, 'Provides social security for the less fortunate in the community.', 3);
  insert into pillar_guide_steps (tenant_id, pillar_id, title, description, sort_order)
