  insert into pillars (tenant_id, slug, title, arabic_text, description, importance, sort_order)
    values (v_tenant_id, 'hajj', 'Hajj (Pilgrimage)', 'الحَجّ', 'The annual pilgrimage to the holy city of Makkah, which every Muslim must perform once in their lifetime if physically and financially able.', 'Hajj symbolizes human equality and submission to Allah, as millions gather in simple white garments regardless of status.', 5) returning id into v_pillar_id;
