  insert into ritual_guide_steps (tenant_id, guide_id, step_number, title, description, icon, sort_order)
    values (v_tenant_id, v_guide_id, 1, 'Niyyah & Bismillah', 'Make the intention in your heart to perform Wudu purely for the sake of Allah, and say “Bismillah”.', 'favorite', 1);
  insert into ritual_guide_steps (tenant_id, guide_id, step_number, title, description, icon, sort_order)
    values (v_tenant_id, v_guide_id, 2, 'Wash Hands', 'Wash both hands up to the wrists three times, ensuring water reaches between the fingers.', 'back_hand', 2);
  insert into ritual_guide_steps (tenant_id, guide_id, step_number, title, description, icon, sort_order)
    values (v_tenant_id, v_guide_id, 3, 'Rinse Mouth', 'Take water into the mouth and rinse thoroughly three times (Madmadah).', 'air', 3);
  insert into ritual_guide_steps (tenant_id, guide_id, step_number, title, description, icon, sort_order)
