  insert into ritual_guide_steps (tenant_id, guide_id, step_number, title, description, icon, sort_order)
    values (v_tenant_id, v_guide_id, 5, 'Wash Face', 'Wash the face from forehead to chin and ear to ear, three times.', 'face', 5);
