  -- ── Ritual Guides: Namaz Lesson ──────────────────
  insert into ritual_guides (tenant_id, guide_type, title, sort_order)
    values (v_tenant_id, 'namaz_lesson', 'Namaz Lesson', 2) returning id into v_guide_id;
  insert into ritual_guide_steps (tenant_id, guide_id, step_number, title, description, arabic_text, sort_order)
    values (v_tenant_id, v_guide_id, 1, 'Sana', '"Glory be to You, O Allah, and all praise is Yours, and blessed is Your name."', 'سُبْحَانَكَ اللَّهُمَّ وَبِحَمْدِكَ وَتَبَارَكَ اسْمُكَ', 1);
  insert into ritual_guide_steps (tenant_id, guide_id, step_number, title, description, arabic_text, sort_order)
    values (v_tenant_id, v_guide_id, 2, 'Al-Fatiha', '"Praise be to Allah, Lord of all the worlds, the Most Gracious, the Most Merciful, Master of the Day of Judgment."', 'الْحَمْدُ لِلَّهِ رَبِّ الْعَالَمِينَ ۝ الرَّحْمَنِ الرَّحِيمِ ۝ مَالِكِ يَوْمِ الدِّينِ', 2);
  insert into ritual_guide_steps (tenant_id, guide_id, step_number, title, description, arabic_text, sort_order)
    values (v_tenant_id, v_guide_id, 3, 'Tasbih of Ruku', '"Glory be to my Lord, the Most Great." (recited 3 times while bowing)', 'سُبْحَانَ رَبِّيَ الْعَظِيمِ', 3);
  insert into ritual_guide_steps (tenant_id, guide_id, step_number, title, description, arabic_text, sort_order)
    values (v_tenant_id, v_guide_id, 4, 'Tasbih of Sajdah', '"Glory be to my Lord, the Most High." (recited 3 times in prostration)', 'سُبْحَانَ رَبِّيَ الْأَعْلَى', 4);
  insert into ritual_guide_steps (tenant_id, guide_id, step_number, title, description, arabic_text, sort_order)
    values (v_tenant_id, v_guide_id, 5, 'Durood Ibrahim', '"O Allah, send blessings upon Muhammad and the family of Muhammad." — recited in the final sitting.', 'اللَّهُمَّ صَلِّ عَلَى مُحَمَّدٍ وَعَلَى آلِ مُحَمَّدٍ', 5);

  -- ── Ritual Guides: How to Perform Namaz ──────────
  insert into ritual_guides (tenant_id, guide_type, title, sort_order)
    values (v_tenant_id, 'namaz_how_to', 'How to Perform', 3) returning id into v_guide_id;
  insert into ritual_guide_steps (tenant_id, guide_id, step_number, title, description, sort_order)
    values (v_tenant_id, v_guide_id, 1, 'Niyyah (Intention)', 'Stand straight facing the Qibla and make your intention in your heart for the specific prayer.', 1);
  insert into ritual_guide_steps (tenant_id, guide_id, step_number, title, description, sort_order)
    values (v_tenant_id, v_guide_id, 2, 'Takbiratul Ihram', 'Raise your hands to your ears and say "Allahu Akbar" to enter the state of prayer.', 2);
  insert into ritual_guide_steps (tenant_id, guide_id, step_number, title, description, sort_order)
    values (v_tenant_id, v_guide_id, 3, 'Qiyam (Standing)', 'Recite Sana, Ta''awwuz, Bismillah, Al-Fatiha, and a Surah from the Quran.', 3);
  insert into ritual_guide_steps (tenant_id, guide_id, step_number, title, description, sort_order)
    values (v_tenant_id, v_guide_id, 4, 'Ruku (Bowing)', 'Bow with your back straight, hands on knees, and recite "Subhana Rabbiyal Azim" three times.', 4);
  insert into ritual_guide_steps (tenant_id, guide_id, step_number, title, description, sort_order)
    values (v_tenant_id, v_guide_id, 5, 'Sajdah (Prostration)', 'Place forehead, nose, palms, knees, and toes on the ground and recite "Subhana Rabbiyal A''la" three times — twice with a short sitting in between.', 5);
  insert into ritual_guide_steps (tenant_id, guide_id, step_number, title, description, sort_order)
    values (v_tenant_id, v_guide_id, 6, 'Tashahhud &amp; Salam', 'In the final sitting, recite At-Tahiyyat, Durood, and Dua, then turn your face right then left saying "Assalamu Alaikum wa Rahmatullah" to end the prayer.', 6);

  -- ── Islamic Q&A ──────────────────────────────────
  insert into qa_items (tenant_id, category, question, answer, sort_order, is_active)
    values (v_tenant_id, 'namaz', 'Namaz ki kitni rakaten hoti hain?', 'Paanch waqt ki namazein hain: Fajr (4), Dhuhr (12), Asr (8), Maghrib (7), Isha (17) — jin mein Fard, Sunnah aur Nafl shamil hain.', 1, true);
  insert into qa_items (tenant_id, category, question, answer, sort_order, is_active)
    values (v_tenant_id, 'namaz', 'Wudu toot jane ki kya wajuhaat hain?', 'Wudu in wajuhaat se toot jata hai: (1) Qaza e hajat, (2) Riyah (gas) khaarij hona, (3) Gehri neend aana, (4) Behoshi, (5) Khoon ya pus nikalna jo beh jaye, (6) Qay karna agar munh bhar ho.', 2, true);
  insert into qa_items (tenant_id, category, question, answer, sort_order, is_active)
    values (v_tenant_id, 'namaz', 'Kya auraton ki namaz mardoon se alag hoti hai?', 'Haan, auraton ke liye namaz ka andaz thoda alag hai — maslan haath baandhne, ruku aur sajdah mein fark hota hai. Auraten jism ko zyada sameta kar namaz ada karti hain.', 3, true);
  insert into qa_items (tenant_id, category, question, answer, sort_order, is_active)
    values (v_tenant_id, 'namaz', 'Qaza namaz kya hoti hai aur kaise ada ki jati hai?', 'Jo namaz apne waqt par ada na ho sake, use Qaza kehte hain. Qaza namaz utni hi rakaton mein ada ki jati hai jitni fard hain — sirf fard rakaten qaza hoti hain, sunnah nahi.', 4, true);
  insert into qa_items (tenant_id, category, question, answer, sort_order, is_active)
    values (v_tenant_id, 'quran', 'Quran mein kitne para, surah aur ayat hain?', 'Quran Majeed mein 30 Para, 114 Surah aur 6,236 Ayaat hain. Sabse badi surah Al-Baqarah (286 ayaat) aur sabse chhoti surah Al-Kawthar (3 ayaat) hai.', 5, true);
  insert into qa_items (tenant_id, category, question, answer, sort_order, is_active)
    values (v_tenant_id, 'quran', 'Quran ka tarjuma parhna kaisa hai?', 'Quran ka tarjuma (translation) parhna jaiz aur mustahsan hai taake maa''na samjha ja sake. Lekin asli sawab Arabic matan parhne se milta hai. Dono mila kar parhna sabse behtar hai.', 6, true);
  insert into qa_items (tenant_id, category, question, answer, sort_order, is_active)
    values (v_tenant_id, 'quran', 'Bila wuzu Quran chu sakte hain?', 'Jumhoor ulama ke mutabiq bila wuzu Quran Majeed ko haath lagana jaiz nahi. Haan, tarjuma ya tafseer ki kitaab bila wuzu chhui ja sakti hai. Mobile ya tablet par bila wuzu parhne mein gunjaaish hai.', 7, true);
  insert into qa_items (tenant_id, category, question, answer, sort_order, is_active)
    values (v_tenant_id, 'roza', 'Roza kis par farz hai?', 'Roza har baligh, aaqil (sane), muqeem (muqim) Muslim mard aur aurat par farz hai. Beemar, musafir, haamilah aur haiz/nifas wali auraten roza chhod sakti hain aur baad mein qaza karein.', 8, true);
  insert into qa_items (tenant_id, category, question, answer, sort_order, is_active)
    values (v_tenant_id, 'roza', 'Roza torne wali cheezein konsi hain?', 'Jaan bujhkar kuch khana peena, jaan bujhkar qay karna, humbistari karna — ye sab roza tor dete hain. Ghalti se kuch kha lena, khwaab mein ehtelaam hona ya neend mein kuch kha lena roza nahi torta.', 9, true);
  insert into qa_items (tenant_id, category, question, answer, sort_order, is_active)
    values (v_tenant_id, 'roza', 'Ramadan mein raat ko kitne baje tak sehri kha sakte hain?', 'Sehri Subah Sadiq (Fajr ka waqt) se pehle pehle khani chahiye. Ihtiyatan Azan se 10-15 minute pehle khaana band kar dena chahiye. Azan ke baad sehri khana jaiz nahi.', 10, true);
  insert into qa_items (tenant_id, category, question, answer, sort_order, is_active)
    values (v_tenant_id, 'zakat', 'Zakat kis par farz hoti hai?', 'Zakat us Muslim par farz hai jis ke paas Nisab ke barabar maal ho aur us par poora ek saal (Haul) guzar jaye. Nisab sone ka: 7.5 tola (87.48g), chandi ka: 52.5 tola (612.36g) ya uske barabar raqam.', 11, true);
  insert into qa_items (tenant_id, category, question, answer, sort_order, is_active)
    values (v_tenant_id, 'zakat', 'Zakat ka nisab kitna hai aur kitni di jati hai?', 'Nisab ki tafeel: Sona 87.48 gram ya Chandi 612.36 gram ya uske barabar cash. Agar itna maal ek saal ke liye paas rahe to kul maal ka 2.5% zakat deni hogi.', 12, true);
  insert into qa_items (tenant_id, category, question, answer, sort_order, is_active)
    values (v_tenant_id, 'aqaid', 'Iman ke kitne arkaan hain?', 'Iman ke 7 arkaan hain: (1) Allah par, (2) Malaika par, (3) Aasmani Kutub par, (4) Anbiya wa Rusul par, (5) Qayamat ke din par, (6) Taqdeer (khair wa shar) par, (7) Marne ke baad dobara uthaye jane par.', 13, true);
  insert into qa_items (tenant_id, category, question, answer, sort_order, is_active)
    values (v_tenant_id, 'aqaid', 'Islam ke 5 arkaan konse hain?', 'Islam ke 5 arkaan hain: (1) Shahada — La ilaha illallah Muhammadur Rasulullah, (2) Salah — Paanch waqt ki namaz, (3) Zakat — Maal ka 2.5% ghareebon ko dena, (4) Sawm — Ramadan ke roze, (5) Hajj — Mustati ke liye.', 14, true);
  insert into qa_items (tenant_id, category, question, answer, sort_order, is_active)
    values (v_tenant_id, 'aqaid', 'Tawheed ka matlab kya hai?', 'Tawheed ka matlab hai Allah ki Wahdat (Oneness) par yakeen rakhna — ke Allah ek hai, uska koi shareek nahi, na ibaadat mein, na sifaat mein, na hukm mein. Ye Islam ka bunyadi aqeedah hai.', 15, true);

