  insert into site_pages (tenant_id, page_key, hero_title, hero_subtitle, content_blocks)
    values (v_tenant_id, 'about', 'Islamic Coaching Institute', 'Guiding Hearts • Illuminating Minds', '[{"type": "paragraph", "text": "Islamic Coaching Institute (ICI) is a dedicated platform for spreading authentic Islamic knowledge and education to Muslims around the world."}, {"type": "paragraph", "text": "Our mission is to make the learning of Quran, Hadith, and Islamic sciences accessible, structured, and easy for every Muslim — young and old."}, {"type": "tags", "items": ["Quran Education", "Hadith", "Islamic Studies", "Daily Duas"]}, {"type": "offerings", "items": ["Quran with 16 Line & 15 Line editions", "Complete Prayer & Wudu Guide", "40 Ahadith & Islamic Books", "Daily Duas & 6 Kalimas", "5 Pillars of Islam explained"]}, {"type": "developer", "name": "ICI Tech Team", "org": "Islamic Coaching Institute"}, {"type": "footer_note", "text": "Made with ❤️ for the Muslim Ummah"}, {"type": "copyright", "text": "© 2024 Islamic Coaching Institute"}]'::jsonb);

